// WorkflowLink A link from one operator's output port to another's input port.
type WorkflowLink struct {
	LinkID string          `json:"linkID"`
	Source WorkflowLinkEnd `json:"source"`
	Target WorkflowLinkEnd `json:"target"`
}

// WorkflowLinkEnd defines model for WorkflowLinkEnd.
type WorkflowLinkEnd struct {
	OperatorID string `json:"operatorID"`
	PortID     string `json:"portID"`
}

// WorkflowOperator An operator instance in a workflow.
type WorkflowOperator struct {
	CustomDisplayName *string `json:"customDisplayName,omitempty"`

	// InputPorts Defaults to one input port input-0 (none for sources).
	InputPorts     *[]WorkflowPort `json:"inputPorts,omitempty"`
	IsDisabled     *bool           `json:"isDisabled,omitempty"`
	MarkedForReuse *bool           `json:"markedForReuse,omitempty"`

	// OperatorID Unique within the workflow, e.g. scan or avg.
	OperatorID string `json:"operatorID"`

	// OperatorProperties Property values following the operator type's JSON Schema. A file property takes a dataset file URI, texera://datasets/{rid}@{vno}/files/{path}.
	OperatorProperties map[string]interface{} `json:"operatorProperties"`

	// OperatorType A built-in operator type, e.g. CSVFileScan, or the URI of a custom operator with `@vno`.
	OperatorType string `json:"operatorType"`

	// OutputPorts Defaults to one output port output-0.
	OutputPorts *[]WorkflowPort `json:"outputPorts,omitempty"`

	// ViewResult Store this operator's output so it can be read after the execution.
	ViewResult *bool `json:"viewResult,omitempty"`
}

// WorkflowPage defines model for WorkflowPage.
type WorkflowPage struct {
	Items []Workflow `json:"items"`

	// NextCursor Opaque cursor for the next page; absent on the last page.
	NextCursor *string `json:"nextCursor,omitempty"`
}

// WorkflowPort A port of an operator in a workflow.
type WorkflowPort struct {
	AllowMultiInputs *bool   `json:"allowMultiInputs,omitempty"`
	DisplayName      *string `json:"displayName,omitempty"`
	IsDynamicPort    *bool   `json:"isDynamicPort,omitempty"`

	// PortID input-<n> or output-<n>.
	PortID string `json:"portID"`
}

// WorkflowSpec defines model for WorkflowSpec.
type WorkflowSpec struct {
	// DefaultComputingUnit The computing unit an execution uses when the request names none.
	DefaultComputingUnit *Uri `json:"defaultComputingUnit,omitempty"`

	// DefaultEnvironment The environment an execution uses when the request names none.
	DefaultEnvironment *Uri `json:"defaultEnvironment,omitempty"`

	// DefaultWarehouse The warehouse an execution keeps its results in when the request names none.
	DefaultWarehouse *Uri               `json:"defaultWarehouse,omitempty"`
	Links            []WorkflowLink     `json:"links"`
	Operators        []WorkflowOperator `json:"operators"`
}

// WorkflowStatus defines model for WorkflowStatus.
type WorkflowStatus struct {
	Executions *int64 `json:"executions,omitempty"`

	// LastExecution Resource id, a UUID.
	LastExecution *Rid `json:"lastExecution,omitempty"`
}

// WorkflowValidation A dry run: the engine's compile result and the plan the catalog would start an execution with.
type WorkflowValidation struct {
	Ok bool `json:"ok"`

	// OperatorErrors Errors per operator id.
	OperatorErrors map[string]interface{} `json:"operatorErrors"`

	// OperatorOutputSchemas Output schemas per operator id and output port id.
	OperatorOutputSchemas map[string]map[string]*[]Attribute `json:"operatorOutputSchemas"`
	PhysicalPlan          interface{}                        `json:"physicalPlan,omitempty"`

	// Plan What the catalog compiled for an execution, as data: what it reads and writes, by URI. No secret and no URL that expires; those are bound when the execution starts and never stored.
	Plan *ExecutionPlan `json:"plan,omitempty"`
}

// WorkflowVersion A version with typed content, served by the kind routes.
type WorkflowVersion struct {
	Content WorkflowSpec `json:"content"`

	// ContentKind What a version holds: a snapshot of the spec, a file manifest over blobs, or an Iceberg table reference.
	ContentKind  ContentKind `json:"contentKind"`
	Contributors *[]Pid      `json:"contributors,omitempty"`
	CreatedAt    time.Time   `json:"createdAt"`

	// CreatedBy Principal id, a UUID.
	CreatedBy Pid `json:"createdBy"`

	// Digest A SHA-256 digest, `sha256:` followed by 64 hex characters.
	Digest Digest `json:"digest"`

	// Kind The kinds. The value is the singular kebab-case kind; the collection is its plural.
	Kind    ResourceKind `json:"kind"`
	Message *string      `json:"message,omitempty"`

	// Origin Where a resource or version came from: the chat turn that produced it, and the agent template that ran the turn.
	Origin *Origin `json:"origin,omitempty"`

	// Rid Resource id, a UUID.
	Rid Rid `json:"rid"`

	// Uri A resource URI: `texera://` followed by the resource's REST path, optionally `@vno` and a subresource path, e.g. `texera://datasets/{rid}@2/files/iris.csv`.
	Uri Uri `json:"uri"`

	// Vno Version number within a resource, starting at 1.
	Vno Vno `json:"vno"`
}

// WorkflowVersionPage defines model for WorkflowVersionPage.
type WorkflowVersionPage struct {
	Items []VersionSummary `json:"items"`

	// NextCursor Opaque cursor for the next page; absent on the last page.
	NextCursor *string `json:"nextCursor,omitempty"`
}

